function hexToRgb(hex){ hex=hex.replace('#',''); if(hex.length===3) hex=hex[0]+hex[0]+hex[1]+hex[1]+hex[2]+hex[2]; if(hex.length!==6) return null; var r=parseInt(hex.substr(0,2),16), g=parseInt(hex.substr(2,2),16), b=parseInt(hex.substr(4,2),16); if([r,g,b].some(function(x){return isNaN(x);})) return null; return {r:r,g:g,b:b}; }
function rgbToHex(r,g,b){ function h(x){ var s=Math.max(0,Math.min(255,Math.round(x))).toString(16); return s.length===1?'0'+s:s; } return '#'+h(r)+h(g)+h(b); }
var EXPORTS={hexToRgb:hexToRgb, rgbToHex:rgbToHex};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ColorPickerForgePure = EXPORTS; }
